column2:
sed -i 's/At r0, select the /At r0, open the /; s/Run \*\*explore\*\* in the workbench Scripts view to check/Run **explore** in Scripts to check/' corpus/projects/chess-search/notes.md
node tools/format-corpus.mjs --check && node tools/format-corpus.mjs && node tools/format-corpus.mjs --check
git diff --check
node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { projectFiles } from './tools/corpus.mjs';
import { loadProject } from './corpus/projects/chess-search/scripts/fixtures.mjs';
const { project, program, backend } = await loadProject();
const { Program } = await import('./dist/typed/program.js');
const { projectSource } = await import('./dist/typed/project.js');
const files = projectFiles(project.id);
const previous = projectSource(project.id, Object.fromEntries(Object.keys(files).map(name => [
  name, execFileSync('git', ['show', \`HEAD:corpus/projects/\${project.id}/\${name}\`], { encoding: 'utf8' }),
])));
const old = Program.fromProject(previous);
assert.equal(old.status, 'ok');
assert.deepEqual(project.meta.inputs, previous.meta.inputs);
assert.equal(backend.lowerToImage(program.origin).image.value.code, backend.lowerToImage(old.origin).image.value.code);
assert.deepEqual(typedRv32.compile(project.source, [], undefined).image, typedRv32.compile(previous.source, [], undefined).image);
assert.deepEqual(program.locate(project.meta.focus), { file: 'main.typed', line: 5 });
assert.match(project.source.split('\n')[project.meta.focus - 1], /chessSearchStep\(board, state\)/);
for (const [id, expectedLine] of [['bb:chessAttacked.16', 52], ['bb:chessAttacked.19', 55]]) {
  assert.deepEqual(program.where(id), [\`position.typed:\${expectedLine}\`]);
}
assert.ok(program.has('fn:chessSearchStep'));
console.log('Identical r0 and reference image bytes, identical input specs, and valid focus links.');
EOF

chess_before=$(mktemp -d /tmp/irwb-017-before.XXXXXX)
for chess_file in corpus/projects/chess-search/*.typed corpus/projects/chess-search/project.json; do
  git show "HEAD:$chess_file" > "$chess_before/\${chess_file:t}" || exit
done
node --input-type=module - "$chess_before" <<'EOF'
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { projectFiles } from './tools/corpus.mjs';
import { loadProject } from './corpus/projects/chess-search/scripts/fixtures.mjs';
const { project, program, backend } = await loadProject();
const { Program } = await import('./dist/typed/program.js');
const { projectSource } = await import('./dist/typed/project.js');
const previous = projectSource(project.id, Object.fromEntries(Object.keys(projectFiles(project.id)).map(name => [
  name, readFileSync(join(process.argv[2], name), 'utf8'),
])));
const old = Program.fromProject(previous);
assert.equal(old.status, 'ok');
assert.deepEqual(project.meta.inputs, previous.meta.inputs);
assert.equal(backend.lowerToImage(program.origin).image.value.code, backend.lowerToImage(old.origin).image.value.code);
assert.deepEqual(typedRv32.compile(project.source, [], undefined).image, typedRv32.compile(previous.source, [], undefined).image);
assert.deepEqual(program.locate(project.meta.focus), { file: 'main.typed', line: 5 });
assert.match(project.source.split('\n')[project.meta.focus - 1], /chessSearchStep\(board, state\)/);
for (const [id, expectedLine] of [['bb:chessAttacked.16', 52], ['bb:chessAttacked.19', 55]]) {
  assert.deepEqual(program.where(id), [\`position.typed:\${expectedLine}\`]);
}
assert.ok(program.has('fn:chessSearchStep'));
console.log('Identical r0 and reference image bytes, identical input specs, and valid focus links.');
EOF

chess_before=$(mktemp -d /tmp/irwb-017-before.XXXXXX)
for chess_file in corpus/projects/chess-search/*.typed corpus/projects/chess-search/project.json; do
  git show "HEAD:$chess_file" > "$chess_before/\${chess_file:t}" || exit
done
node --input-type=module - "$chess_before" <<'EOF'
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { projectFiles } from './tools/corpus.mjs';
import { loadProject } from './corpus/projects/chess-search/scripts/fixtures.mjs';
const { project, program, backend } = await loadProject();
const { Program } = await import('./dist/typed/program.js');
const { projectSource } = await import('./dist/typed/project.js');
const { createWb } = await import('./dist/workbench/index.js');
const files = projectFiles(project.id);
const previous = projectSource(project.id, Object.fromEntries(Object.keys(files).map(name => [
  name, readFileSync(join(process.argv[2], name), 'utf8'),
])));
const old = Program.fromProject(previous);
assert.equal(old.status, 'ok');
assert.deepEqual(project.meta.inputs, previous.meta.inputs);
assert.equal(backend.lowerToImage(program.origin).image.value.code, backend.lowerToImage(old.origin).image.value.code);
assert.deepEqual(typedRv32.compile(project.source, [], undefined).image, typedRv32.compile(previous.source, [], undefined).image);
const wb = createWb({ projects: [{ id: project.id, files }] });
wb.projects.open(project.id);
assert.deepEqual(wb.current.locate(project.meta.focus), { file: 'main.typed', line: 5 });
assert.match(project.source.split('\n')[project.meta.focus - 1], /chessSearchStep\(board, state\)/);
for (const [id, expectedLine] of [['bb:chessAttacked.16', 52], ['bb:chessAttacked.19', 55]]) {
  assert.deepEqual(wb.current.where(id), [\`position.typed:\${expectedLine}\`]);
}
assert.ok(wb.current.has('fn:chessSearchStep'));
console.log('Identical r0 and reference image bytes, identical input specs, and valid focus links.');
EOF
git diff --check

git diff -- corpus/projects/chess-search/main.typed corpus/projects/chess-search/scripts/explore.js tests/typed/chess-search.test.mjs
node --input-type=module <<'EOF'
import {readdirSync,readFileSync} from 'node:fs';
const root='corpus/projects/chess-search/';
for (const file of [...readdirSync(root).filter(f=>f.endsWith('.typed')), 'scripts/explore.js', 'project.json','notes.md']) {
  console.log(file,Math.max(...readFileSync(root+file,'utf8').split('\n').map(line=>line.length)));
}
EOF
